	protected void insertSalary_payment( List<Salary_payment> salary_payments )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = salary_payments.size();
		if ( salary_paymentStmtSize != size ) {
			if ( salary_paymentStmt != null ) {
				salary_paymentStmt.close();
			}
			String values = "(?,?,?,?,?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			salary_paymentStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO salary_payment (id,domain,salary,type,payment_concept,description,expression,amount,irpf,quote)"  
				+" VALUES " + valuesList.toString()  );
			
			salary_paymentStmtSize = size;
		}

		int offset = 1;
			
		for (Salary_payment salary_payment : salary_payments) {
			if ( salary_payment.id == null )
				salary_paymentStmt.setNull(offset++, 4);
			else
				salary_paymentStmt.setInt(offset++, salary_payment.id);
			if ( salary_payment.domain == null )
				salary_paymentStmt.setNull(offset++, 4);
			else
				salary_paymentStmt.setInt(offset++, salary_payment.domain);
			if ( salary_payment.salary == null )
				salary_paymentStmt.setNull(offset++, 4);
			else
				salary_paymentStmt.setInt(offset++, salary_payment.salary);
			if ( salary_payment.type == null )
				salary_paymentStmt.setNull(offset++, -6);
			else
				salary_paymentStmt.setShort(offset++, salary_payment.type);
			if ( salary_payment.payment_concept == null )
				salary_paymentStmt.setNull(offset++, 12);
			else
				salary_paymentStmt.setString(offset++, salary_payment.payment_concept);
			if ( salary_payment.description == null )
				salary_paymentStmt.setNull(offset++, 12);
			else
				salary_paymentStmt.setString(offset++, salary_payment.description);
			if ( salary_payment.expression == null )
				salary_paymentStmt.setNull(offset++, 12);
			else
				salary_paymentStmt.setString(offset++, salary_payment.expression);
			if ( salary_payment.amount == null )
				salary_paymentStmt.setNull(offset++, 8);
			else
				salary_paymentStmt.setDouble(offset++, salary_payment.amount);
			if ( salary_payment.irpf == null )
				salary_paymentStmt.setNull(offset++, 8);
			else
				salary_paymentStmt.setDouble(offset++, salary_payment.irpf);
			if ( salary_payment.quote == null )
				salary_paymentStmt.setNull(offset++, 8);
			else
				salary_paymentStmt.setDouble(offset++, salary_payment.quote);
		}
		salary_paymentStmt.executeUpdate();
		salary_payments.clear();
		salary_paymentInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Salary_payments in {} milliseconds.", size, salary_paymentInserted, elapsed );		
	}
		
