	protected void insertBrand( List<Brand> brands )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = brands.size();
		if ( brandStmtSize != size ) {
			if ( brandStmt != null ) {
				brandStmt.close();
			}
			String values = "(?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			brandStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO brand (id,domain,name)"  
				+" VALUES " + valuesList.toString()  );
			
			brandStmtSize = size;
		}

		int offset = 1;
			
		for (Brand brand : brands) {
			if ( brand.id == null )
				brandStmt.setNull(offset++, 4);
			else
				brandStmt.setInt(offset++, brand.id);
			if ( brand.domain == null )
				brandStmt.setNull(offset++, 4);
			else
				brandStmt.setInt(offset++, brand.domain);
			if ( brand.name == null )
				brandStmt.setNull(offset++, 12);
			else
				brandStmt.setString(offset++, brand.name);
		}
		brandStmt.executeUpdate();
		brands.clear();
		brandInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Brands in {} milliseconds.", size, brandInserted, elapsed );		
	}
		
