	private int raddressStmtSize = 0;

	private int raddressInserted = 0;

	private List<Raddress> raddresss = 
		new LinkedList<Raddress>();

	private PreparedStatement raddressStmt = null;

	public static class Raddress {
		protected Integer id; 
		protected Integer domain; 
		protected Integer registry; 
		protected Short type; 
		protected String recipient; 
		protected String street_type; 
		protected String address; 
		protected String number; 
		protected String address2; 
		protected String address3; 
		protected String zip; 
		protected String city; 
		protected Integer geozone; 
		protected String alias; 
		protected String municipality_code; 
	}
	
	protected void insertRaddress( List<Raddress> raddresss )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = raddresss.size();
		if ( raddressStmtSize != size ) {
			if ( raddressStmt != null ) {
				raddressStmt.close();
			}
			String values = "(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			raddressStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO raddress (id,domain,registry,type,recipient,street_type,address,number,address2,address3,zip,city,geozone,alias,municipality_code)"  
				+" VALUES " + valuesList.toString()  );
			
			raddressStmtSize = size;
		}

		int offset = 1;
			
		for (Raddress raddress : raddresss) {
			if ( raddress.id == null )
				raddressStmt.setNull(offset++, 4);
			else
				raddressStmt.setInt(offset++, raddress.id);
			if ( raddress.domain == null )
				raddressStmt.setNull(offset++, 4);
			else
				raddressStmt.setInt(offset++, raddress.domain);
			if ( raddress.registry == null )
				raddressStmt.setNull(offset++, 4);
			else
				raddressStmt.setInt(offset++, raddress.registry);
			if ( raddress.type == null )
				raddressStmt.setNull(offset++, -6);
			else
				raddressStmt.setShort(offset++, raddress.type);
			if ( raddress.recipient == null )
				raddressStmt.setNull(offset++, 12);
			else
				raddressStmt.setString(offset++, raddress.recipient);
			if ( raddress.street_type == null )
				raddressStmt.setNull(offset++, 12);
			else
				raddressStmt.setString(offset++, raddress.street_type);
			if ( raddress.address == null )
				raddressStmt.setNull(offset++, 12);
			else
				raddressStmt.setString(offset++, raddress.address);
			if ( raddress.number == null )
				raddressStmt.setNull(offset++, 12);
			else
				raddressStmt.setString(offset++, raddress.number);
			if ( raddress.address2 == null )
				raddressStmt.setNull(offset++, 12);
			else
				raddressStmt.setString(offset++, raddress.address2);
			if ( raddress.address3 == null )
				raddressStmt.setNull(offset++, 12);
			else
				raddressStmt.setString(offset++, raddress.address3);
			if ( raddress.zip == null )
				raddressStmt.setNull(offset++, 12);
			else
				raddressStmt.setString(offset++, raddress.zip);
			if ( raddress.city == null )
				raddressStmt.setNull(offset++, 12);
			else
				raddressStmt.setString(offset++, raddress.city);
			if ( raddress.geozone == null )
				raddressStmt.setNull(offset++, 4);
			else
				raddressStmt.setInt(offset++, raddress.geozone);
			if ( raddress.alias == null )
				raddressStmt.setNull(offset++, 12);
			else
				raddressStmt.setString(offset++, raddress.alias);
			if ( raddress.municipality_code == null )
				raddressStmt.setNull(offset++, 12);
			else
				raddressStmt.setString(offset++, raddress.municipality_code);
		}
		raddressStmt.executeUpdate();
		raddresss.clear();
		raddressInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Raddresss in {} milliseconds.", size, raddressInserted, elapsed );		
	}
		
		private int raddressId = -1;
		
		private void initRaddressId() 
		throws SQLException  {
			ResultSet rs = null;
			Statement stmt = null;
			try {
				stmt = mysqlConnection.createStatement();
				rs = stmt.executeQuery("SELECT max(id) FROM `raddress`" );
				Integer max = null;
				if ( rs.next() ) {		
					max = rs.getInt(1);
				}
				this.raddressId = max == null ? 0 : max;
			}
			finally {
				if ( rs != null )
					rs.close(); 
				if ( stmt != null )
					stmt.close(); 
			}
		}

		public int nextRaddressId() {
			return ++this.raddressId;
		} 

		public void setRaddressId(Integer raddressId) {
			this.raddressId = raddressId;
		} 
	
	protected void flushRaddress( )
	throws SQLException {
		flushRaddress(false);
	}	

	private void flushRaddress( boolean close )
	throws SQLException {
		if ( ! raddresss.isEmpty() )
			insertRaddress(raddresss);
		if ( close && raddressStmt != null )
			raddressStmt.close();
	}	

