	private PreparedStatement campaignStmt = null;

	public static class Campaign {
		protected Integer id; 
		protected Integer domain; 
		protected Integer campaign_type; 
		protected String description; 
		protected Integer process; 
		protected Date start_date; 
		protected Date end_date; 
		protected Integer workgroup; 
		protected Boolean manual; 
		protected Short status; 
	}
	
	protected void insertCampaign( List<Campaign> campaigns )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = campaigns.size();
		if ( campaignStmtSize != size ) {
			if ( campaignStmt != null ) {
				campaignStmt.close();
			}
			String values = "(?,?,?,?,?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			campaignStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO campaign (id,domain,campaign_type,description,process,start_date,end_date,workgroup,manual,status)"  
				+" VALUES " + valuesList.toString()  );
			
			campaignStmtSize = size;
		}

		int offset = 1;
			
		for (Campaign campaign : campaigns) {
			if ( campaign.id == null )
				campaignStmt.setNull(offset++, 4);
			else
				campaignStmt.setInt(offset++, campaign.id);
			if ( campaign.domain == null )
				campaignStmt.setNull(offset++, 4);
			else
				campaignStmt.setInt(offset++, campaign.domain);
			if ( campaign.campaign_type == null )
				campaignStmt.setNull(offset++, 4);
			else
				campaignStmt.setInt(offset++, campaign.campaign_type);
			if ( campaign.description == null )
				campaignStmt.setNull(offset++, 12);
			else
				campaignStmt.setString(offset++, campaign.description);
			if ( campaign.process == null )
				campaignStmt.setNull(offset++, 4);
			else
				campaignStmt.setInt(offset++, campaign.process);
			if ( campaign.start_date == null )
				campaignStmt.setNull(offset++, 91);
			else
				campaignStmt.setDate(offset++, campaign.start_date);
			if ( campaign.end_date == null )
				campaignStmt.setNull(offset++, 91);
			else
				campaignStmt.setDate(offset++, campaign.end_date);
			if ( campaign.workgroup == null )
				campaignStmt.setNull(offset++, 4);
			else
				campaignStmt.setInt(offset++, campaign.workgroup);
			if ( campaign.manual == null )
				campaignStmt.setNull(offset++, -7);
			else
				campaignStmt.setBoolean(offset++, campaign.manual);
			if ( campaign.status == null )
				campaignStmt.setNull(offset++, -6);
			else
				campaignStmt.setShort(offset++, campaign.status);
		}
		campaignStmt.executeUpdate();
		campaigns.clear();
		campaignInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Campaigns in {} milliseconds.", size, campaignInserted, elapsed );		
	}
		
		private int campaignId = -1;
		
		private void initCampaignId() 
		throws SQLException  {
			ResultSet rs = null;
			Statement stmt = null;
			try {
				stmt = mysqlConnection.createStatement();
				rs = stmt.executeQuery("SELECT max(id) FROM `campaign`" );
				Integer max = null;
				if ( rs.next() ) {		
					max = rs.getInt(1);
				}
				this.campaignId = max == null ? 0 : max;
			}
			finally {
				if ( rs != null )
					rs.close(); 
				if ( stmt != null )
					stmt.close(); 
			}
		}

		public int nextCampaignId() {
			return ++this.campaignId;
		} 

		public void setCampaignId(Integer campaignId) {
			this.campaignId = campaignId;
		} 
	
	protected void flushCampaign( )
	throws SQLException {
		flushCampaign(false);
	}	

	private void flushCampaign( boolean close )
	throws SQLException {
		if ( ! campaigns.isEmpty() )
			insertCampaign(campaigns);
		if ( close && campaignStmt != null )
			campaignStmt.close();
	}	

