	protected void insertLoan( List<Loan> loans )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = loans.size();
		if ( loanStmtSize != size ) {
			if ( loanStmt != null ) {
				loanStmt.close();
			}
			String values = "(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			loanStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO loan (id,domain,description,loan_date,term,interest,review,amount,expenses,rbank,security_level,fee_amount,recurrence,pay_day,status,account)"  
				+" VALUES " + valuesList.toString()  );
			
			loanStmtSize = size;
		}

		int offset = 1;
			
		for (Loan loan : loans) {
			if ( loan.id == null )
				loanStmt.setNull(offset++, 4);
			else
				loanStmt.setInt(offset++, loan.id);
			if ( loan.domain == null )
				loanStmt.setNull(offset++, 4);
			else
				loanStmt.setInt(offset++, loan.domain);
			if ( loan.description == null )
				loanStmt.setNull(offset++, 12);
			else
				loanStmt.setString(offset++, loan.description);
			if ( loan.loan_date == null )
				loanStmt.setNull(offset++, 91);
			else
				loanStmt.setDate(offset++, loan.loan_date);
			if ( loan.term == null )
				loanStmt.setNull(offset++, 12);
			else
				loanStmt.setString(offset++, loan.term);
			if ( loan.interest == null )
				loanStmt.setNull(offset++, 12);
			else
				loanStmt.setString(offset++, loan.interest);
			if ( loan.review == null )
				loanStmt.setNull(offset++, 12);
			else
				loanStmt.setString(offset++, loan.review);
			if ( loan.amount == null )
				loanStmt.setNull(offset++, 8);
			else
				loanStmt.setDouble(offset++, loan.amount);
			if ( loan.expenses == null )
				loanStmt.setNull(offset++, 8);
			else
				loanStmt.setDouble(offset++, loan.expenses);
			if ( loan.rbank == null )
				loanStmt.setNull(offset++, 4);
			else
				loanStmt.setInt(offset++, loan.rbank);
			if ( loan.security_level == null )
				loanStmt.setNull(offset++, -6);
			else
				loanStmt.setShort(offset++, loan.security_level);
			if ( loan.fee_amount == null )
				loanStmt.setNull(offset++, 8);
			else
				loanStmt.setDouble(offset++, loan.fee_amount);
			if ( loan.recurrence == null )
				loanStmt.setNull(offset++, 4);
			else
				loanStmt.setInt(offset++, loan.recurrence);
			if ( loan.pay_day == null )
				loanStmt.setNull(offset++, 4);
			else
				loanStmt.setInt(offset++, loan.pay_day);
			if ( loan.status == null )
				loanStmt.setNull(offset++, -6);
			else
				loanStmt.setShort(offset++, loan.status);
			if ( loan.account == null )
				loanStmt.setNull(offset++, 4);
			else
				loanStmt.setInt(offset++, loan.account);
		}
		loanStmt.executeUpdate();
		loans.clear();
		loanInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Loans in {} milliseconds.", size, loanInserted, elapsed );		
	}
		
