	private int auto_conceptStmtSize = 0;

	private int auto_conceptInserted = 0;

	private List<Auto_concept> auto_concepts = 
		new LinkedList<Auto_concept>();

	private PreparedStatement auto_conceptStmt = null;

	public static class Auto_concept {
		protected Integer id; 
		protected Integer domain; 
		protected String description; 
	}
	
	protected void insertAuto_concept( List<Auto_concept> auto_concepts )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = auto_concepts.size();
		if ( auto_conceptStmtSize != size ) {
			if ( auto_conceptStmt != null ) {
				auto_conceptStmt.close();
			}
			String values = "(?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			auto_conceptStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO auto_concept (id,domain,description)"  
				+" VALUES " + valuesList.toString()  );
			
			auto_conceptStmtSize = size;
		}

		int offset = 1;
			
		for (Auto_concept auto_concept : auto_concepts) {
			if ( auto_concept.id == null )
				auto_conceptStmt.setNull(offset++, 4);
			else
				auto_conceptStmt.setInt(offset++, auto_concept.id);
			if ( auto_concept.domain == null )
				auto_conceptStmt.setNull(offset++, 4);
			else
				auto_conceptStmt.setInt(offset++, auto_concept.domain);
			if ( auto_concept.description == null )
				auto_conceptStmt.setNull(offset++, 1);
			else
				auto_conceptStmt.setString(offset++, auto_concept.description);
		}
		auto_conceptStmt.executeUpdate();
		auto_concepts.clear();
		auto_conceptInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Auto_concepts in {} milliseconds.", size, auto_conceptInserted, elapsed );		
	}
		
		private int auto_conceptId = -1;
		
		private void initAuto_conceptId() 
		throws SQLException  {
			ResultSet rs = null;
			Statement stmt = null;
			try {
				stmt = mysqlConnection.createStatement();
				rs = stmt.executeQuery("SELECT max(id) FROM `auto_concept`" );
				Integer max = null;
				if ( rs.next() ) {		
					max = rs.getInt(1);
				}
				this.auto_conceptId = max == null ? 0 : max;
			}
			finally {
				if ( rs != null )
					rs.close(); 
				if ( stmt != null )
					stmt.close(); 
			}
		}

		public int nextAuto_conceptId() {
			return ++this.auto_conceptId;
		} 

		public void setAuto_conceptId(Integer auto_conceptId) {
			this.auto_conceptId = auto_conceptId;
		} 
	
	protected void flushAuto_concept( )
	throws SQLException {
		flushAuto_concept(false);
	}	

	private void flushAuto_concept( boolean close )
	throws SQLException {
		if ( ! auto_concepts.isEmpty() )
			insertAuto_concept(auto_concepts);
		if ( close && auto_conceptStmt != null )
			auto_conceptStmt.close();
	}	

