	private int noticeStmtSize = 0;

	private int noticeInserted = 0;

	private List<Notice> notices = 
		new LinkedList<Notice>();

	private PreparedStatement noticeStmt = null;

	public static class Notice {
		protected Integer id; 
		protected Integer domain; 
		protected Timestamp date; 
		protected Integer sender; 
		protected Integer work_group; 
		protected Integer recipient; 
		protected String source; 
		protected String company; 
		protected String phone; 
		protected String subject; 
		protected Short status; 
		protected Short type; 
		protected Short priority; 
		protected Integer notice; 
	}
	
	protected void insertNotice( List<Notice> notices )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = notices.size();
		if ( noticeStmtSize != size ) {
			if ( noticeStmt != null ) {
				noticeStmt.close();
			}
			String values = "(?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			noticeStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO notice (id,domain,date,sender,work_group,recipient,source,company,phone,subject,status,type,priority,notice)"  
				+" VALUES " + valuesList.toString()  );
			
			noticeStmtSize = size;
		}

		int offset = 1;
			
		for (Notice notice : notices) {
			if ( notice.id == null )
				noticeStmt.setNull(offset++, 4);
			else
				noticeStmt.setInt(offset++, notice.id);
			if ( notice.domain == null )
				noticeStmt.setNull(offset++, 4);
			else
				noticeStmt.setInt(offset++, notice.domain);
			if ( notice.date == null )
				noticeStmt.setNull(offset++, 93);
			else
				noticeStmt.setTimestamp(offset++, notice.date);
			if ( notice.sender == null )
				noticeStmt.setNull(offset++, 4);
			else
				noticeStmt.setInt(offset++, notice.sender);
			if ( notice.work_group == null )
				noticeStmt.setNull(offset++, 4);
			else
				noticeStmt.setInt(offset++, notice.work_group);
			if ( notice.recipient == null )
				noticeStmt.setNull(offset++, 4);
			else
				noticeStmt.setInt(offset++, notice.recipient);
			if ( notice.source == null )
				noticeStmt.setNull(offset++, 12);
			else
				noticeStmt.setString(offset++, notice.source);
			if ( notice.company == null )
				noticeStmt.setNull(offset++, 12);
			else
				noticeStmt.setString(offset++, notice.company);
			if ( notice.phone == null )
				noticeStmt.setNull(offset++, 12);
			else
				noticeStmt.setString(offset++, notice.phone);
			if ( notice.subject == null )
				noticeStmt.setNull(offset++, -1);
			else
				noticeStmt.setString(offset++, notice.subject);
			if ( notice.status == null )
				noticeStmt.setNull(offset++, -6);
			else
				noticeStmt.setShort(offset++, notice.status);
			if ( notice.type == null )
				noticeStmt.setNull(offset++, -6);
			else
				noticeStmt.setShort(offset++, notice.type);
			if ( notice.priority == null )
				noticeStmt.setNull(offset++, -6);
			else
				noticeStmt.setShort(offset++, notice.priority);
			if ( notice.notice == null )
				noticeStmt.setNull(offset++, 4);
			else
				noticeStmt.setInt(offset++, notice.notice);
		}
		noticeStmt.executeUpdate();
		notices.clear();
		noticeInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Notices in {} milliseconds.", size, noticeInserted, elapsed );		
	}
		
		private int noticeId = -1;
		
		private void initNoticeId() 
		throws SQLException  {
			ResultSet rs = null;
			Statement stmt = null;
			try {
				stmt = mysqlConnection.createStatement();
				rs = stmt.executeQuery("SELECT max(id) FROM `notice`" );
				Integer max = null;
				if ( rs.next() ) {		
					max = rs.getInt(1);
				}
				this.noticeId = max == null ? 0 : max;
			}
			finally {
				if ( rs != null )
					rs.close(); 
				if ( stmt != null )
					stmt.close(); 
			}
		}

		public int nextNoticeId() {
			return ++this.noticeId;
		} 

		public void setNoticeId(Integer noticeId) {
			this.noticeId = noticeId;
		} 
	
	protected void flushNotice( )
	throws SQLException {
		flushNotice(false);
	}	

	private void flushNotice( boolean close )
	throws SQLException {
		if ( ! notices.isEmpty() )
			insertNotice(notices);
		if ( close && noticeStmt != null )
			noticeStmt.close();
	}	

