	private int registryStmtSize = 0;

	private int registryInserted = 0;

	private List<Registry> registrys = 
		new LinkedList<Registry>();

	private PreparedStatement registryStmt = null;

	public static class Registry {
		protected Integer id; 
		protected Integer domain; 
		protected String document; 
		protected Short document_type; 
		protected String document_country; 
		protected String name; 
		protected String alias; 
		protected Short type; 
		protected String nationality; 
		protected Short security_level; 
	}
	
	protected void insertRegistry( List<Registry> registrys )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = registrys.size();
		if ( registryStmtSize != size ) {
			if ( registryStmt != null ) {
				registryStmt.close();
			}
			String values = "(?,?,?,?,?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			registryStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO registry (id,domain,document,document_type,document_country,name,alias,type,nationality,security_level)"  
				+" VALUES " + valuesList.toString()  );
			
			registryStmtSize = size;
		}

		int offset = 1;
			
		for (Registry registry : registrys) {
			if ( registry.id == null )
				registryStmt.setNull(offset++, 4);
			else
				registryStmt.setInt(offset++, registry.id);
			if ( registry.domain == null )
				registryStmt.setNull(offset++, 4);
			else
				registryStmt.setInt(offset++, registry.domain);
			if ( registry.document == null )
				registryStmt.setNull(offset++, 12);
			else
				registryStmt.setString(offset++, registry.document);
			if ( registry.document_type == null )
				registryStmt.setNull(offset++, -6);
			else
				registryStmt.setShort(offset++, registry.document_type);
			if ( registry.document_country == null )
				registryStmt.setNull(offset++, 12);
			else
				registryStmt.setString(offset++, registry.document_country);
			if ( registry.name == null )
				registryStmt.setNull(offset++, 12);
			else
				registryStmt.setString(offset++, registry.name);
			if ( registry.alias == null )
				registryStmt.setNull(offset++, 12);
			else
				registryStmt.setString(offset++, registry.alias);
			if ( registry.type == null )
				registryStmt.setNull(offset++, -6);
			else
				registryStmt.setShort(offset++, registry.type);
			if ( registry.nationality == null )
				registryStmt.setNull(offset++, 12);
			else
				registryStmt.setString(offset++, registry.nationality);
			if ( registry.security_level == null )
				registryStmt.setNull(offset++, -6);
			else
				registryStmt.setShort(offset++, registry.security_level);
		}
		registryStmt.executeUpdate();
		registrys.clear();
		registryInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Registrys in {} milliseconds.", size, registryInserted, elapsed );		
	}
		
		private int registryId = -1;
		
		private void initRegistryId() 
		throws SQLException  {
			ResultSet rs = null;
			Statement stmt = null;
			try {
				stmt = mysqlConnection.createStatement();
				rs = stmt.executeQuery("SELECT max(id) FROM `registry`" );
				Integer max = null;
				if ( rs.next() ) {		
					max = rs.getInt(1);
				}
				this.registryId = max == null ? 0 : max;
			}
			finally {
				if ( rs != null )
					rs.close(); 
				if ( stmt != null )
					stmt.close(); 
			}
		}

		public int nextRegistryId() {
			return ++this.registryId;
		} 

		public void setRegistryId(Integer registryId) {
			this.registryId = registryId;
		} 
	
	protected void flushRegistry( )
	throws SQLException {
		flushRegistry(false);
	}	

	private void flushRegistry( boolean close )
	throws SQLException {
		if ( ! registrys.isEmpty() )
			insertRegistry(registrys);
		if ( close && registryStmt != null )
			registryStmt.close();
	}	

