		private int purchaseId = -1;
		
		private void initPurchaseId() 
		throws SQLException  {
			ResultSet rs = null;
			Statement stmt = null;
			try {
				stmt = mysqlConnection.createStatement();
				rs = stmt.executeQuery("SELECT max(id) FROM `purchase`" );
				Integer max = null;
				if ( rs.next() ) {		
					max = rs.getInt(1);
				}
				this.purchaseId = max == null ? 0 : max;
			}
			finally {
				if ( rs != null )
					rs.close(); 
				if ( stmt != null )
					stmt.close(); 
			}
		}

		public int nextPurchaseId() {
			return ++this.purchaseId;
		} 

		public void setPurchaseId(Integer purchaseId) {
			this.purchaseId = purchaseId;
		} 
	
	protected void flushPurchase( )
	throws SQLException {
		flushPurchase(false);
	}	

	private void flushPurchase( boolean close )
	throws SQLException {
		if ( ! purchases.isEmpty() )
			insertPurchase(purchases);
		if ( close && purchaseStmt != null )
			purchaseStmt.close();
	}	

