	private int roomStmtSize = 0;

	private int roomInserted = 0;

	private List<Room> rooms = 
		new LinkedList<Room>();

	private PreparedStatement roomStmt = null;

	public static class Room {
		protected Integer asset; 
		protected Integer domain; 
		protected Integer hotel; 
		protected Integer item; 
		protected Short status; 
		protected Timestamp last_cleaning_date; 
		protected Boolean active; 
	}
	
	protected void insertRoom( List<Room> rooms )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = rooms.size();
		if ( roomStmtSize != size ) {
			if ( roomStmt != null ) {
				roomStmt.close();
			}
			String values = "(?,?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			roomStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO room (asset,domain,hotel,item,status,last_cleaning_date,active)"  
				+" VALUES " + valuesList.toString()  );
			
			roomStmtSize = size;
		}

		int offset = 1;
			
		for (Room room : rooms) {
			if ( room.asset == null )
				roomStmt.setNull(offset++, 4);
			else
				roomStmt.setInt(offset++, room.asset);
			if ( room.domain == null )
				roomStmt.setNull(offset++, 4);
			else
				roomStmt.setInt(offset++, room.domain);
			if ( room.hotel == null )
				roomStmt.setNull(offset++, 4);
			else
				roomStmt.setInt(offset++, room.hotel);
			if ( room.item == null )
				roomStmt.setNull(offset++, 4);
			else
				roomStmt.setInt(offset++, room.item);
			if ( room.status == null )
				roomStmt.setNull(offset++, -6);
			else
				roomStmt.setShort(offset++, room.status);
			if ( room.last_cleaning_date == null )
				roomStmt.setNull(offset++, 93);
			else
				roomStmt.setTimestamp(offset++, room.last_cleaning_date);
			if ( room.active == null )
				roomStmt.setNull(offset++, -7);
			else
				roomStmt.setBoolean(offset++, room.active);
		}
		roomStmt.executeUpdate();
		rooms.clear();
		roomInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Rooms in {} milliseconds.", size, roomInserted, elapsed );		
	}
		
	
	protected void flushRoom( )
	throws SQLException {
		flushRoom(false);
	}	

	private void flushRoom( boolean close )
	throws SQLException {
		if ( ! rooms.isEmpty() )
			insertRoom(rooms);
		if ( close && roomStmt != null )
			roomStmt.close();
	}	

	/**
	 * Room
	 * @param asset Identificador del Activo
	 * @param domain Identificador del Dominio
	 * @param hotel Identificador del Hotel
	 * @param item Identificador del Producto
	 * @param status Estado de la Habitacion
	 * @param last_cleaning_date Ultima fecha de limpieza
	 * @param active Indica si la Habitacion esta activa o no
	 * @throws SQLException
	*/
	protected void insertRoom(Integer asset, Integer domain, Integer hotel, Integer item, Short status, Timestamp last_cleaning_date, Boolean active)
	throws SQLException {

		Room room_ = new Room();
		room_.asset = asset;
		room_.domain = domain;
		room_.hotel = hotel;
		room_.item = item;
		room_.status = status;
		room_.last_cleaning_date = last_cleaning_date;
		room_.active = active;

		rooms.add(room_);
		
		int roomCount = rooms.size();
		
		if ( 62 * roomCount >=  this.maxAllowedPacket ){
			insertRoom(rooms);
		} 
	}



