	private int targetStmtSize = 0;

	private int targetInserted = 0;

	private List<Target> targets = 
		new LinkedList<Target>();

	private PreparedStatement targetStmt = null;

	public static class Target {
		protected Integer registry; 
		protected Integer domain; 
		protected Integer tariff; 
		protected Short advertising; 
		protected Boolean surcharge; 
		protected Boolean withholding; 
		protected Short transaction; 
		protected Short status; 
		protected Integer scope; 
		protected String creation_user; 
		protected Timestamp creation_date; 
		protected String modification_user; 
		protected Timestamp modification_date; 
	}
	
	protected void insertTarget( List<Target> targets )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = targets.size();
		if ( targetStmtSize != size ) {
			if ( targetStmt != null ) {
				targetStmt.close();
			}
			String values = "(?,?,?,?,?,?,?,?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			targetStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO target (registry,domain,tariff,advertising,surcharge,withholding,transaction,status,scope,creation_user,creation_date,modification_user,modification_date)"  
				+" VALUES " + valuesList.toString()  );
			
			targetStmtSize = size;
		}

		int offset = 1;
			
		for (Target target : targets) {
			if ( target.registry == null )
				targetStmt.setNull(offset++, 4);
			else
				targetStmt.setInt(offset++, target.registry);
			if ( target.domain == null )
				targetStmt.setNull(offset++, 4);
			else
				targetStmt.setInt(offset++, target.domain);
			if ( target.tariff == null )
				targetStmt.setNull(offset++, 4);
			else
				targetStmt.setInt(offset++, target.tariff);
			if ( target.advertising == null )
				targetStmt.setNull(offset++, -6);
			else
				targetStmt.setShort(offset++, target.advertising);
			if ( target.surcharge == null )
				targetStmt.setNull(offset++, -7);
			else
				targetStmt.setBoolean(offset++, target.surcharge);
			if ( target.withholding == null )
				targetStmt.setNull(offset++, -7);
			else
				targetStmt.setBoolean(offset++, target.withholding);
			if ( target.transaction == null )
				targetStmt.setNull(offset++, -6);
			else
				targetStmt.setShort(offset++, target.transaction);
			if ( target.status == null )
				targetStmt.setNull(offset++, -6);
			else
				targetStmt.setShort(offset++, target.status);
			if ( target.scope == null )
				targetStmt.setNull(offset++, 4);
			else
				targetStmt.setInt(offset++, target.scope);
			if ( target.creation_user == null )
				targetStmt.setNull(offset++, 12);
			else
				targetStmt.setString(offset++, target.creation_user);
			if ( target.creation_date == null )
				targetStmt.setNull(offset++, 93);
			else
				targetStmt.setTimestamp(offset++, target.creation_date);
			if ( target.modification_user == null )
				targetStmt.setNull(offset++, 12);
			else
				targetStmt.setString(offset++, target.modification_user);
			if ( target.modification_date == null )
				targetStmt.setNull(offset++, 93);
			else
				targetStmt.setTimestamp(offset++, target.modification_date);
		}
		targetStmt.executeUpdate();
		targets.clear();
		targetInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Targets in {} milliseconds.", size, targetInserted, elapsed );		
	}
		
	
	protected void flushTarget( )
	throws SQLException {
		flushTarget(false);
	}	

	private void flushTarget( boolean close )
	throws SQLException {
		if ( ! targets.isEmpty() )
			insertTarget(targets);
		if ( close && targetStmt != null )
			targetStmt.close();
	}	

