	protected void insertAmortization( List<Amortization> amortizations )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = amortizations.size();
		if ( amortizationStmtSize != size ) {
			if ( amortizationStmt != null ) {
				amortizationStmt.close();
			}
			String values = "(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			amortizationStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO amortization (id,domain,description,initial_date,deadline,amount,fee_period,sale_amount,comments,invest_asset,fixed_asset_account,accumulated_account,allocation_account,percentage,security_level)"  
				+" VALUES " + valuesList.toString()  );
			
			amortizationStmtSize = size;
		}

		int offset = 1;
			
		for (Amortization amortization : amortizations) {
			if ( amortization.id == null )
				amortizationStmt.setNull(offset++, 4);
			else
				amortizationStmt.setInt(offset++, amortization.id);
			if ( amortization.domain == null )
				amortizationStmt.setNull(offset++, 4);
			else
				amortizationStmt.setInt(offset++, amortization.domain);
			if ( amortization.description == null )
				amortizationStmt.setNull(offset++, 12);
			else
				amortizationStmt.setString(offset++, amortization.description);
			if ( amortization.initial_date == null )
				amortizationStmt.setNull(offset++, 91);
			else
				amortizationStmt.setDate(offset++, amortization.initial_date);
			if ( amortization.deadline == null )
				amortizationStmt.setNull(offset++, 91);
			else
				amortizationStmt.setDate(offset++, amortization.deadline);
			if ( amortization.amount == null )
				amortizationStmt.setNull(offset++, 8);
			else
				amortizationStmt.setDouble(offset++, amortization.amount);
			if ( amortization.fee_period == null )
				amortizationStmt.setNull(offset++, -6);
			else
				amortizationStmt.setShort(offset++, amortization.fee_period);
			if ( amortization.sale_amount == null )
				amortizationStmt.setNull(offset++, 8);
			else
				amortizationStmt.setDouble(offset++, amortization.sale_amount);
			if ( amortization.comments == null )
				amortizationStmt.setNull(offset++, -1);
			else
				amortizationStmt.setString(offset++, amortization.comments);
			if ( amortization.invest_asset == null )
				amortizationStmt.setNull(offset++, 4);
			else
				amortizationStmt.setInt(offset++, amortization.invest_asset);
			if ( amortization.fixed_asset_account == null )
				amortizationStmt.setNull(offset++, 4);
			else
				amortizationStmt.setInt(offset++, amortization.fixed_asset_account);
			if ( amortization.accumulated_account == null )
				amortizationStmt.setNull(offset++, 4);
			else
				amortizationStmt.setInt(offset++, amortization.accumulated_account);
			if ( amortization.allocation_account == null )
				amortizationStmt.setNull(offset++, 4);
			else
				amortizationStmt.setInt(offset++, amortization.allocation_account);
			if ( amortization.percentage == null )
				amortizationStmt.setNull(offset++, 8);
			else
				amortizationStmt.setDouble(offset++, amortization.percentage);
			if ( amortization.security_level == null )
				amortizationStmt.setNull(offset++, -6);
			else
				amortizationStmt.setShort(offset++, amortization.security_level);
		}
		amortizationStmt.executeUpdate();
		amortizations.clear();
		amortizationInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Amortizations in {} milliseconds.", size, amortizationInserted, elapsed );		
	}
		
