	protected void insertRdir_staff( List<Rdir_staff> rdir_staffs )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = rdir_staffs.size();
		if ( rdir_staffStmtSize != size ) {
			if ( rdir_staffStmt != null ) {
				rdir_staffStmt.close();
			}
			String values = "(?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			rdir_staffStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO rdir_staff (id,domain,registry,document,name,shareholder,representative,director,percent_share,share_number,nominal_value,due_date,representative_labor,charge_description)"  
				+" VALUES " + valuesList.toString()  );
			
			rdir_staffStmtSize = size;
		}

		int offset = 1;
			
		for (Rdir_staff rdir_staff : rdir_staffs) {
			if ( rdir_staff.id == null )
				rdir_staffStmt.setNull(offset++, 4);
			else
				rdir_staffStmt.setInt(offset++, rdir_staff.id);
			if ( rdir_staff.domain == null )
				rdir_staffStmt.setNull(offset++, 4);
			else
				rdir_staffStmt.setInt(offset++, rdir_staff.domain);
			if ( rdir_staff.registry == null )
				rdir_staffStmt.setNull(offset++, 4);
			else
				rdir_staffStmt.setInt(offset++, rdir_staff.registry);
			if ( rdir_staff.document == null )
				rdir_staffStmt.setNull(offset++, 12);
			else
				rdir_staffStmt.setString(offset++, rdir_staff.document);
			if ( rdir_staff.name == null )
				rdir_staffStmt.setNull(offset++, 12);
			else
				rdir_staffStmt.setString(offset++, rdir_staff.name);
			if ( rdir_staff.shareholder == null )
				rdir_staffStmt.setNull(offset++, -7);
			else
				rdir_staffStmt.setBoolean(offset++, rdir_staff.shareholder);
			if ( rdir_staff.representative == null )
				rdir_staffStmt.setNull(offset++, -7);
			else
				rdir_staffStmt.setBoolean(offset++, rdir_staff.representative);
			if ( rdir_staff.director == null )
				rdir_staffStmt.setNull(offset++, -7);
			else
				rdir_staffStmt.setBoolean(offset++, rdir_staff.director);
			if ( rdir_staff.percent_share == null )
				rdir_staffStmt.setNull(offset++, 8);
			else
				rdir_staffStmt.setDouble(offset++, rdir_staff.percent_share);
			if ( rdir_staff.share_number == null )
				rdir_staffStmt.setNull(offset++, 4);
			else
				rdir_staffStmt.setInt(offset++, rdir_staff.share_number);
			if ( rdir_staff.nominal_value == null )
				rdir_staffStmt.setNull(offset++, 8);
			else
				rdir_staffStmt.setDouble(offset++, rdir_staff.nominal_value);
			if ( rdir_staff.due_date == null )
				rdir_staffStmt.setNull(offset++, 91);
			else
				rdir_staffStmt.setDate(offset++, rdir_staff.due_date);
			if ( rdir_staff.representative_labor == null )
				rdir_staffStmt.setNull(offset++, -7);
			else
				rdir_staffStmt.setBoolean(offset++, rdir_staff.representative_labor);
			if ( rdir_staff.charge_description == null )
				rdir_staffStmt.setNull(offset++, 12);
			else
				rdir_staffStmt.setString(offset++, rdir_staff.charge_description);
		}
		rdir_staffStmt.executeUpdate();
		rdir_staffs.clear();
		rdir_staffInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Rdir_staffs in {} milliseconds.", size, rdir_staffInserted, elapsed );		
	}
		
