		private int salesId = -1;
		
		private void initSalesId() 
		throws SQLException  {
			ResultSet rs = null;
			Statement stmt = null;
			try {
				stmt = mysqlConnection.createStatement();
				rs = stmt.executeQuery("SELECT max(id) FROM `sales`" );
				Integer max = null;
				if ( rs.next() ) {		
					max = rs.getInt(1);
				}
				this.salesId = max == null ? 0 : max;
			}
			finally {
				if ( rs != null )
					rs.close(); 
				if ( stmt != null )
					stmt.close(); 
			}
		}

		public int nextSalesId() {
			return ++this.salesId;
		} 

		public void setSalesId(Integer salesId) {
			this.salesId = salesId;
		} 
	
	protected void flushSales( )
	throws SQLException {
		flushSales(false);
	}	

	private void flushSales( boolean close )
	throws SQLException {
		if ( ! saless.isEmpty() )
			insertSales(saless);
		if ( close && salesStmt != null )
			salesStmt.close();
	}	

