	protected void insertCnae( List<Cnae> cnaes )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = cnaes.size();
		if ( cnaeStmtSize != size ) {
			if ( cnaeStmt != null ) {
				cnaeStmt.close();
			}
			String values = "(?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			cnaeStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO cnae (id,code,title)"  
				+" VALUES " + valuesList.toString()  );
			
			cnaeStmtSize = size;
		}

		int offset = 1;
			
		for (Cnae cnae : cnaes) {
			if ( cnae.id == null )
				cnaeStmt.setNull(offset++, 4);
			else
				cnaeStmt.setInt(offset++, cnae.id);
			if ( cnae.code == null )
				cnaeStmt.setNull(offset++, 12);
			else
				cnaeStmt.setString(offset++, cnae.code);
			if ( cnae.title == null )
				cnaeStmt.setNull(offset++, 12);
			else
				cnaeStmt.setString(offset++, cnae.title);
		}
		cnaeStmt.executeUpdate();
		cnaes.clear();
		cnaeInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Cnaes in {} milliseconds.", size, cnaeInserted, elapsed );		
	}
		
