	public int insertAsset_feature(Integer domain, Integer asset, Integer feature)
	throws SQLException {
		int id = nextAsset_featureId();

		Asset_feature asset_feature_ = new Asset_feature();
		asset_feature_.id = id;
		asset_feature_.domain = domain;
		asset_feature_.asset = asset;
		asset_feature_.feature = feature;

		asset_features.add(asset_feature_);
		
		int asset_featureCount = asset_features.size();
		
		if ( 40 * asset_featureCount >=  this.maxAllowedPacket ){
			insertAsset_feature(asset_features);
			asset_features.clear();
		} 
		return id;
	}


